import React, {
  MouseEvent,
  FocusEvent,
  HTMLProps,
  useImperativeHandle,
  useRef,
  useState,
  useLayoutEffect,
} from 'react';
import { Calendar } from '@hexa-ui/icons';
import { format } from 'date-fns';
import InputWrapper, { InputWrapperProps } from '../InputWrapper';
import { StyledInput, InputContainer } from './DatePickerInput.styles';
import IconButton from '../../icon-button/IconButton';
import { formatedDate, dateIsValid } from './utils';
import { getTranslateLabel, getTranslationsDate } from '../../../utils';

export interface DatePickerInputProps
  extends Omit<HTMLProps<HTMLInputElement>, 'children' | 'size' | 'css' | 'value' | 'onChange'>,
    Omit<InputWrapperProps, 'children' | 'counter' | 'maxCounter' | 'characterCounter'> {
  size?: 'small' | 'large';
  width?: string | number;
  onClick?: (event: MouseEvent) => void;
  value?: Date[];
  onChange: (value: Date[]) => void;
  mode?: 'single' | 'range';
  customLocale: 'pt' | 'en' | 'es';
}

export const DatePickerInput = React.forwardRef(
  (
    {
      hint,
      label,
      legend,
      required,
      optionalText = '(Optional)',
      hasError,
      disabled = false,
      errorText,
      labelProps,
      value,
      onChange,
      size = 'large',
      placeholder = 'Insert your date',
      id,
      width,
      onClick,
      mode = 'single',
      customLocale,
      ...otherProps
    }: DatePickerInputProps,
    forwardedRef: React.ForwardedRef<HTMLInputElement>
  ): JSX.Element => {
    const [inputValue, setInputValue] = useState('');
    const [focused, setFocused] = useState(false);
    const innerRef = useRef<HTMLInputElement>(null);
    useImperativeHandle(forwardedRef, () => innerRef?.current as HTMLInputElement);

    useLayoutEffect(() => {
      const locale = getTranslationsDate(customLocale);
      const formatDate = getTranslateLabel('formatDate', customLocale);
      const toLabel = getTranslateLabel('to', customLocale);

      if (mode === 'single') {
        setInputValue(value?.[0] ? format(value?.[0], formatDate, { locale }) : '');
      } else {
        setInputValue(
          value?.[0]
            ? `${format(value?.[0], formatDate, { locale })} ${toLabel} ${format(
                value?.[1] || value?.[0],
                formatDate,
                { locale }
              )}`
            : ''
        );
      }
    }, [value, mode, customLocale]);

    const mappedPlaceholder = !label && !required ? `${placeholder} ${optionalText}` : placeholder;

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setInputValue(e.target.value);
    };

    return (
      <InputWrapper
        labelProps={{ ...labelProps, htmlFor: id }}
        label={label}
        hint={hint}
        legend={legend}
        hasError={hasError}
        disabled={disabled}
        required={required}
        errorText={errorText}
        optionalText={optionalText}
        width={width}
      >
        <InputContainer disabled={disabled} hasError={hasError} focused={focused}>
          <StyledInput
            {...otherProps}
            id={id}
            ref={innerRef}
            value={inputValue}
            onChange={handleChange}
            disabled={disabled}
            size={size}
            readOnly={mode === 'range'}
            css={{ cursor: mode === 'range' ? 'pointer' : 'unset' }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && inputValue.length >= 8 && dateIsValid(inputValue)) {
                setInputValue(
                  formatedDate(inputValue, {
                    month: 'short',
                    day: '2-digit',
                    year: 'numeric',
                  })
                );
                onChange([new Date(inputValue)]);
              }
            }}
            placeholder={mappedPlaceholder?.trim()}
            onFocus={(e: FocusEvent<HTMLInputElement>) => {
              if (!hasError) setFocused(true);
              otherProps?.onFocus?.(e);
            }}
            onBlur={(e: FocusEvent<HTMLInputElement>) => {
              setFocused(false);
              otherProps?.onBlur?.(e);

              if (inputValue.length >= 8 && dateIsValid(inputValue)) {
                setInputValue(
                  formatedDate(inputValue, {
                    month: 'short',
                    day: '2-digit',
                    year: 'numeric',
                  })
                );
                onChange([new Date(inputValue)]);
              }
            }}
          />
          <IconButton
            type="button"
            variant="inherit"
            icon={Calendar}
            size="medium"
            onClick={onClick}
            disabled={disabled}
          />
        </InputContainer>
      </InputWrapper>
    );
  }
);

export default DatePickerInput;
